// ---------------------------------------------------------------------------
// ImGui's IM_ASSERT (overlay_imconfig.h): log, never abort() inside the game.
// ---------------------------------------------------------------------------
namespace { std::atomic<int> g_assertFailures{0}; }

void GageImGuiAssertFailed(const char* expr, const char* file, int line)
{
    const int n = ++g_assertFailures;
    if (n <= 20)
        GLOGE("overlay: ImGui assertion failed: %s (%s:%d)%s", expr, file, line,
              n == 20 ? " [further assertions are counted, not logged]" : "");
}

